mapper.update:
update goods_order set go_receiver_name=${go_receiver_name}, go_receiver_phone=${go_receiver_phone}
,go_receiver_post = ${go_receiver_post}, go_receiver_address = ${go_receiver_address},
 go_receiver_address_detail = ${go_receiver_address_detail}, go_status = 1 where go_num = ${go_num}
